  "components": [
    {
      "type": "claim",
      "quote": "The task of the [entity] is to ensure the cross-departmental coordination of projects, resources and administrative services to advance the digital transformation process within the Federal Administration.",
      "gist": "A specific office coordinates projects, resources, and services for digital transformation in the Federal Administration."
    },
    {
      "type": "entity",
      "quote": "Federal Chancellor's staff office",
      "gist": "The office responsible for cross-departmental coordination of digital transformation."
    },
    {
      "type": "claim",
      "quote": "The [entity] provides support in organisational and administrative matters, and in preparing Federal Council meetings and the follow-up work to the meetings.",
      "gist": "The Federal Chancellor's staff office supports organizational and administrative tasks and prepares Federal Council meetings."
    },
    {
      "type": "entity",
      "quote": "Federal Data Protection and Information Commissioner",
      "gist": "The authority responsible for data protection and information freedom laws."
    },
    {
      "type": "claim",
      "quote": "The [entity] has two areas of responsibility: the Federal Act on Data Protection and the Federal Act on Freedom of Information in the Administration.",
      "gist": "The Federal Data Protection and Information Commissioner oversees two specific federal acts."
    }
  ]
}
